// The base64 of makeSilentWav(50) in e2e/wav.ts: 8000 Hz, 1 channel, 16-bit
// PCM, 400 samples at zero, 50 ms, 844 bytes. 50 ms is under the 0.1 s limit.
export const SILENT_WAV = "data:audio/wav;base64,";

const quiet = () => {};

// The two shared audio elements of a book (design "5", Audio). Every method
// is synchronous and is called in the click or key handler, so play() runs
// inside the user gesture (iOS). A play() that fails is quiet.
export class PlayerAudio {
  constructor(
    private readonly narration: HTMLAudioElement,
    private readonly sfx: HTMLAudioElement,
  ) {}

  // "Start": the narration of page 1, then the silent clip that unlocks the
  // sound-effect element (design "5", "Sound-effect unlock").
  start(src: string): void {
    this.playNarration(src);
    this.playSfx(SILENT_WAV);
  }

  playNarration(src: string): void {
    this.narration.src = src;
    this.narration.play().catch(quiet);
  }

  stopNarration(): void {
    this.narration.pause();
  }

  playSfx(src: string): void {
    this.sfx.src = src;
    this.sfx.play().catch(quiet);
  }

  stopAll(): void {
    this.narration.pause();
    this.sfx.pause();
  }
}
